{
  "status": "STABLE",
  "core_findings": [
    "Positive items generally outrank sampled negatives across all four datasets. Electronics and Industrial_and_Scientific have weaker separation, with negative-beats-positive rates of 5.71% and 5.37%, versus 2.07% for Movies_and_TV and 3.32% for CDs_and_Vinyl.",
    "Representations retain substantial variation rather than showing complete collapse. Appended-mask user representations have lower effective rank in Industrial_and_Scientific and Electronics, despite real-item effective ranks near 49–54 across datasets."
  ],
  "key_implications": [
    "Measured masked-target discrimination is broadly healthy, but these training probes do not establish validation HR@10 or recommendation diversity.",
    "User representations concentrate variation in fewer directions than item embeddings, particularly for Industrial_and_Scientific and Electronics.",
    "Training branch allocation remains unknown: approximately 19–20% terminal-position coverage describes the diagnostic loader only."
  ],
  "evidence": {
    "headline_metrics": {
      "Electronics:pos_neg_margin_p10": 0.6623,
      "Movies_and_TV:pos_neg_margin_p10": 2.8445,
      "Industrial_and_Scientific:appended_mask_users_rankme": 24.3300,
      "Industrial_and_Scientific:real_items_rankme": 49.6040
    },
    "brief_metric_read": {
      "pos_neg_margin_p10": "Lower-tail separation remains positive, but Electronics has less margin.",
      "representation_geometry": "Nonzero centered variance and substantial effective ranks argue against complete collapse.",
      "training_branch_allocation": "Null for all categories; actual training allocation is unavailable."
    }
  }
}
